// 串子模式（反串）
// 说明：
//  · hooks 方式实现（before-llm-messages），把「反串」身份注入到系统提示末尾，覆盖平时的说话风格
//  · 不读写任何本机文件、不联网、不改宿主核心
//  · 红线：只玩圈子梗，不碰真实政治人物/事件/人群，不点名攻击群里的人
const DEFAULTS = {
  "enabled": true,
  "minutes": 5,
  "triggers": "开串,来串,串一个,串子,串一下,串个,来段串,给我串,串子模式,进串,如何评价,怎么评价,怎样评价,如何看待,怎么看待,评价一下,评价下,给个评价,点评一下,点评下,点评,锐评,锐评一下,说说看,评一评,吐槽一下,喷一下",
  "stopWords": "收,别串了,不串了,收工,正常说,停串",
  "maxLines": 3
};
let cfg = () => ({ ...DEFAULTS });
let log = () => {};
const active = new Map();
const splitList = (v) => String(v || '').split(/[,，、\s]+/).map((s) => s.trim()).filter(Boolean);

function lastUserText(messages) {
  if (!Array.isArray(messages)) return '';
  for (let i = messages.length - 1; i >= 0; i -= 1) {
    const m = messages[i];
    if (!m || m.role !== 'user') continue;
    if (typeof m.content === 'string') return m.content;
    if (Array.isArray(m.content)) return m.content.filter((x) => x && x.type === 'text').map((x) => String(x.text || '')).join('\n');
  }
  return '';
}
function currentTurnText(messages) {
  const all = Array.isArray(messages)
    ? messages.filter((m) => m && m.role === 'user').map((m) => (typeof m.content === 'string' ? m.content : '')).join('\n')
    : '';
  const i = all.lastIndexOf('【本次唤醒】');
  if (i < 0) return all;
  const j = all.indexOf('【此刻状态】', i);
  return all.slice(i, j > 0 ? j : Math.min(all.length, i + 1200));
}
function SAFE_INJECT(messages, text) {
  const sys = Array.isArray(messages) ? messages.find((m) => m && m.role === 'system') : null;
  if (!sys) return false;
  if (typeof sys.content === 'string') { sys.content += text; return true; }
  if (Array.isArray(sys.content)) { sys.content.push({ type: 'text', text }); return true; }
  return false;
}


