export function setup(api) {
  cfg = () => {
    const c = (api && typeof api.config === 'function' ? api.config() : {}) || {};
    return { ...DEFAULTS, ...c };
  };
  log = (api && typeof api.log === 'function') ? api.log : () => {};
}

export const hooks = {
  'before-llm-messages': (ctx = {}) => {
    try {
      const conf = cfg();
      if (conf.enabled === false) return;
      const chatKey = String(ctx?.chatKey || '');
      if (!chatKey) return;
      const messages = ctx?.messages;
      if (!Array.isArray(messages) || !messages.length) return;
      const text = currentTurnText(messages);
      if (!text) return;

      const now = Date.now();
      const st = active.get(chatKey);
      const alive = st && st.until > now;

  const exitHints = ['睡了','睡觉','晚安','困了','去睡','下班','散会','先这样','拜拜','不聊了','吃饭去','洗澡'];
      const hitStop = splitList(conf.stopWords).find((w) => text.includes(w)) 
        || (String(text).length < 40 ? exitHints.find((w) => text.includes(w)) : undefined);
      if (hitStop) {
        active.delete(chatKey);
        log('串子模式退出（' + hitStop + '）');
        const sys = messages.find((m) => m && m.role === 'system');
        if (sys && typeof sys.content === 'string') sys.content += '\n\n【串子模式：已退出】恢复正常说话，别再抬杠。';
        return;
      }

      const hitTrigger = splitList(conf.triggers).find((w) => text.includes(w));
      if (hitTrigger) {
        const minutes = Math.max(1, Math.min(30, Number(conf.minutes) || 10));
        const pool = pickPool(text);
        active.set(chatKey, { until: now + minutes * 60000, poolName: pool.name, pool });
        SAFE_INJECT(messages, '\n' + buildBlock(minutes, pool));
        active.delete(chatKey); // 一次性：串完即退
        log('进入串子模式（' + hitTrigger + '，' + minutes + ' 分钟，领域=' + pool.name + '）');
        return;
      }

      if (st && !alive) { active.delete(chatKey); return; }
      if (alive) {
        const remainMin = Math.max(1, Math.round((st.until - now) / 60000));
        SAFE_INJECT(messages, '\n' + buildBlock(remainMin, st.pool || pickPool(text)));
      }
    } catch { /* 插件出错绝不影响主流程 */ }
  },
};
